-- Migration: Create Clientes table for autofill&#10;IF NOT EXISTS (SELECT * FROM sysobjects WHERE name=&#x27;Clientes&#x27; AND xtype=&#x27;U&#x27;)&#10;BEGIN&#10;    CREATE TABLE Clientes (&#10;        ClienteID INT IDENTITY(1,1) PRIMARY KEY,&#10;        Nombre NVARCHAR(200) NOT NULL,&#10;        Correo NVARCHAR(200),&#10;        Telefono NVARCHAR(50),&#10;        Documento NVARCHAR(50),&#10;        Direccion NVARCHAR(500),&#10;        FechaCreacion DATETIME DEFAULT GETDATE(),&#10;        FechaUltimoUso DATETIME DEFAULT GETDATE(),&#10;        Usos INT DEFAULT 1&#10;    );&#10;    PRINT &#x27;✅ Clientes table created&#x27;&#10;END&#10;ELSE&#10;    PRINT &#x27;ℹ️ Clientes table already exists&#x27;&#10;&#10;-- Indexes for fast name search&#10;IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name = &#x27;IX_Clientes_Nombre&#x27;)&#10;BEGIN&#10;    CREATE NONCLUSTERED INDEX IX_Clientes_Nombre ON Clientes(Nombre);&#10;    PRINT &#x27;✅ Index IX_Clientes_Nombre created&#x27;&#10;END
